conditions.text:
body: `fix: cards

Docs-card-for: ${OLD.slice(0, 11)} skipped — ${SKIP_CLAIM_REASON}
Docs-card-for: ${OLD2.slice(0, 11)} ${FULL_CARD.replace('Docs-card: ', '')}
`,

importedSubjects:
+profile
 for path in factory:
  assert path in text,path+

invocation.run:
git fetch --no-tags --quiet origin "${BASE_REF}:refs/remotes/origin/${BASE_REF}"
git rev-parse --verify "origin/${BASE_REF}" >/dev/null \
  || { echo "::error::base ref origin/${BASE_REF} not resolvable — refusing to skip the backstop"; exit 1; }

cd "$GITHUB_WORKSPACE"
npx --prefix packages/core vitest run --reporter=default packages/core/audit-self/audit-ai-docs.test.ts || \
  { echo "::error::framework audits failed (ts-server consumer)"; exit 1; }

cd "$GITHUB_WORKSPACE"
npx --prefix packages/core vitest run --reporter=default packages/core/audit-self/audit-ai-docs.test.ts || \
  { echo "::error::framework audits failed (react-next consumer)"; exit 1; }

# Per AIF SKILL.md "Append machine-readable gate result". Orchestrators
# downstream of /aif-verify parse this block; emission is non-blocking
# and structurally compatible with aif-comparison.md §7 11.1.
GATE_RESULT=$(npm --prefix packages/core run validate --silent -- --aif-gate-result "$GITHUB_WORKSPACE")
{
  echo '## aif-gate-result (rules)';
  echo '```json';
  echo "$GATE_RESULT";
  echo '```';
} >> "$GITHUB_STEP_SUMMARY"
echo "✓ aif-gate-result emitted to job summary"

npm ci --prefix packages/core --silent
cd packages/core
rc=0
NO_COLOR=1 npx --no-install vitest run install/wire-eslint-r2.test.ts \
  -t 'two spellings|URL path|linked project root' --reporter=default \
  --reporter=json --outputFile.json="$RUNNER_TEMP/r2-spec.json" > "$RUNNER_TEMP/r2-spec.log" 2>&1 || rc=$?
cat "$RUNNER_TEMP/r2-spec.log"
[ "$rc" -eq 0 ] || exit "$rc"
# A skipped case (no ts-morph, no ESLint) passes vitest too: require each one by name, and
# require this runner's TEMP to have a second spelling, or the 8.3 arm was never exercised.
node - "$RUNNER_TEMP/r2-spec.json" "$RUNNER_TEMP/r2-spec.log" <<'JS'
const fs = require('node:fs');
const [json, log] = process.argv.slice(2);
const passed = JSON.parse(fs.readFileSync(json, 'utf8')).testResults
  .flatMap((f) => f.assertionResults).filter((a) => a.status === 'passed').map((a) => a.fullName);
const want = ['config under the link, cwd physical', 'the temp dir as the OS spells it',
  'another drive (no relative path exists)', 'own config wired through a linked project root'];
const missing = want.filter((w) => !passed.some((n) => n.includes(w)));
if (missing.length) { console.log(`::error::did not run: ${missing.join(' | ')}`); process.exit(1); }
const m = /\[r2-spec\] tmpdir=(.*) realpathSync=(.*) realpathSync\.native=(.*)/.exec(fs.readFileSync(log, 'utf8'));
if (!m) { console.log('::error::no [r2-spec] measurement line'); process.exit(1); }
const [, spelled, js, native] = m;
const line = `TEMP as spelled: ${spelled}\nrealpathSync:    ${js}\nrealpathSync.native: ${native}`;
if (process.env.GITHUB_STEP_SUMMARY) fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, `\`\`\`\n${line}\n\`\`\`\n`);
console.log(line);
if (spelled.trim() === native.trim()) { console.log('::error::TEMP has one spelling on this runner: the short-name case was not exercised'); process.exit(1); }
JS

set -euo pipefail
repo_json="$(gh api "repos/${{ github.repository }}")"
{
  echo "stars=$(echo "$repo_json" | jq -r '.stargazers_count')"
  echo "forks=$(echo "$repo_json" | jq -r '.forks_count')"
} >> "$GITHUB_OUTPUT"
